-- fdh-c-check: op row count of OPD
-- GENERATED by scripts/export_rules.mjs from BKH Insight src/app/api/fdh/c-check/checks.ts - do not edit by hand
-- params (2, in order of the placeholders): start, end
-- returns n
WITH p AS (SELECT CAST(? AS DATE) AS s, CAST(? AS DATE) AS e) SELECT SUM(COALESCE(oa.c, 1)) AS n FROM p JOIN ovst v ON v.vstdate BETWEEN p.s AND p.e LEFT JOIN ipt i ON i.vn = v.vn LEFT JOIN referin rf_in ON rf_in.vn = v.vn LEFT JOIN referout rf_out ON rf_out.vn = v.vn LEFT JOIN (SELECT o.hn, o.nextdate, COUNT(*) AS c FROM p JOIN oapp o ON o.nextdate BETWEEN p.s AND p.e GROUP BY o.hn, o.nextdate) oa ON oa.hn = v.hn AND oa.nextdate = v.vstdate;
